  "Controlo dos níveis de colesterol.": { en: "Helps control cholesterol levels.", es: "Control de los niveles de colesterol." },
  "Extrato seco de alho (Allium sativum L.), bolbo (3% alicina)": { en: "Dry garlic extract (Allium sativum L.), bulb (3% allicin)", es: "Extracto seco de ajo (Allium sativum L.), bulbo (3% alicina)" },
