  "Extrato de levedura de arroz vermelho (Monascus purpureus L.) (3% monacolina K)": { en: "Red yeast rice extract (Monascus purpureus L.) (3% monacolin K)", es: "Extracto de levadura de arroz rojo (Monascus purpureus L.) (3% monacolina K)" },
  "Agente de volume: celulose microcristalina": { en: "Bulking agent: microcrystalline cellulose", es: "Agente de carga: celulosa microcristalina" },
