  "Antiaglomerante: sais de ácidos gordos de magnésio": { en: "Anti-caking agent: magnesium salts of fatty acids", es: "Antiaglomerante: sales magnésicas de ácidos grasos" },
  "Extrato seco de cana-de-açúcar (Saccharum officinarum) (10% octacosanol, 98% policosanol)": { en: "Dry sugar cane extract (Saccharum officinarum) (10% octacosanol, 98% policosanol)", es: "Extracto seco de caña de azúcar (Saccharum officinarum) (10% octacosanol, 98% policosanol)" },
